export type PerformanceReportTranslationKey = (typeof performanceReportRows)[number][0];
export type PerformanceReportTranslationParams = Record<string, string | number>;

export const performanceReportTranslationKeys = performanceReportRows.map(
  (row) => row[0]
) as readonly PerformanceReportTranslationKey[];

export const performanceReportTranslations = Object.fromEntries(
  logStudioLocaleOrder.map((locale, localeIndex) => [
    locale,
    Object.fromEntries(performanceReportRows.map((row) => [row[0], row[localeIndex + 1]])),
  ])
) as Record<LocaleCode, Record<PerformanceReportTranslationKey, string>>;

export function performanceReportT(
  locale: LocaleCode,
  key: PerformanceReportTranslationKey,
  params: PerformanceReportTranslationParams = {}
) {
  const template = performanceReportTranslations[locale][key];
  return template.replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (match, name: string) =>
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : match
  );
}

