type LogStudioUiTranslationKey = (typeof logStudioRows)[number][0];
export type LogStudioTranslationKey = LogStudioUiTranslationKey | ResultTranslationKey;
export type LogStudioTranslationParams = Record<string, string | number>;

const allResultRows = [...logStudioResultRows, ...logAnalyzerResultRows] as const;
const rawResultCatalogs = Object.fromEntries(
  logStudioLocaleOrder.map((locale, localeIndex) => [
    locale,
    Object.fromEntries(allResultRows.map((row) => [row[0], row[localeIndex + 1]])),
  ])
) as Record<LocaleCode, Partial<Record<ResultTranslationKey, string>>>;

const resultCatalogs = Object.fromEntries(
  logStudioLocaleOrder.map((locale) => {
    const raw = rawResultCatalogs[locale];
    const studio = Object.fromEntries(
      logStudioResultMessageKeys.map((key) => [key, raw[key]])
    );
    const analyzer = Object.fromEntries(
      logAnalyzerMessageKeys.map((key) => [key, raw[analyzerMessageAliases[key]]])
    );
    return [locale, { ...studio, ...analyzer }];
  })
) as Record<LocaleCode, Record<ResultTranslationKey, string>>;

const catalogs = Object.fromEntries(
  logStudioLocaleOrder.map((locale, localeIndex) => [
    locale,
    {
      ...Object.fromEntries(logStudioRows.map((row) => [row[0], row[localeIndex + 1]])),
      ...resultCatalogs[locale],
    },
  ])
) as Record<LocaleCode, Record<LogStudioTranslationKey, string>>;

export const logStudioTranslationKeys = [
  ...logStudioRows.map((row) => row[0]),
  ...logStudioResultMessageKeys,
  ...logAnalyzerMessageKeys,
] as const;
export const logStudioTranslations = catalogs;

export const logStudioExactLocaleOrder = logStudioLocaleOrder.filter(
  (locale): locale is Exclude<LocaleCode, "en"> => locale !== "en"
);

/**
 * Static English-source rows for the shared exact-text compatibility layer.
 * Parameterized templates stay in the typed Studio API because matching an
 * interpolated DOM string by source text would be ambiguous.
 */
export const logStudioExactTranslations = Object.fromEntries(
  logStudioRows
    .filter((row) => !/\{[a-zA-Z][a-zA-Z0-9]*\}/.test(row[1]))
    .map((row) => [row[1], row.slice(2)])
) as Record<string, readonly string[]>;

export function logStudioT(
  locale: LocaleCode,
  key: LogStudioTranslationKey,
  params: LogStudioTranslationParams = {}
) {
  const template = catalogs[locale]?.[key] ?? catalogs.en[key];
  return template.replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (match, name: string) =>
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : match
  );
}

const analysisErrorKeys: Record<string, LogStudioTranslationKey> = {
  "A comma, semicolon or tab-delimited numeric table could not be detected.": "tableDetectionError",
  "The log needs a header and at least one numeric data row.": "headerNumericError",
  "Select a delimited log or paste numeric log rows to begin.": "selectDelimitedError",
  "No numeric channels were detected in the retained rows.": "noChannelsError",
};

export function logStudioAnalysisErrorT(locale: LocaleCode, source?: string | null) {
  const key = source ? analysisErrorKeys[source] : undefined;
  return logStudioT(locale, key ?? "noChannelsError");
}

